import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CCXDMzJr.js";const u=JSON.parse('{"title":"前言","description":"","frontmatter":{},"headers":[],"relativePath":"preface.md","filePath":"preface.md","lastUpdated":1786693096000}'),s={name:"preface.md"};function n(d,e,i,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><h2 id="为什么要写这本书" tabindex="-1">为什么要写这本书 <a class="header-anchor" href="#为什么要写这本书" aria-label="Permalink to &quot;为什么要写这本书&quot;">​</a></h2><p>DeepSeek Harness（<code>dsh</code>）是 DeepSeek AI 开源的 Agent 运行时（agent harness）。它与大多数&quot;以 LLM 调用为核心的框架&quot;不同：<strong>整个产品由插件构成，没有任何特权核心</strong>。模型适配器、工具注册表、会话日志、Agent 循环、沙箱、Web 界面……每一个能力都是一枚 Cordis 插件，都能在配置层被替换、被拦截、被扩展。</p><p>这种&quot;一切皆插件&quot;的架构让 dsh 拥有极强的可组合性，但也让初次接触它的人感到困惑：入口在哪里？插件如何装载？服务如何解析？事件如何在三层事件域中流转？</p><p>本书试图回答这些问题。它以源码为唯一依据，沿着 <strong>CLI 入口 → 启动链路 → Cordis 框架 → 核心子系统 → Web 客户端 → 插件开发</strong> 的主线，逐层拆解 dsh 的实现，并在最后一部分系统总结插件开发技巧。</p><h2 id="本书面向的读者" tabindex="-1">本书面向的读者 <a class="header-anchor" href="#本书面向的读者" aria-label="Permalink to &quot;本书面向的读者&quot;">​</a></h2><ul><li>想理解 Agent 运行时架构设计的工程师；</li><li>计划为 dsh 编写插件、或在其上构建产品的开发者；</li><li>对 Cordis 插件框架感兴趣、希望看到真实工业级用法的读者。</li></ul><p>阅读本书需要具备 JavaScript/TypeScript 基础，并了解基本的 Node.js 概念（ESM、事件循环等）。书中所有关键结论都标注了源码位置（<code>包路径/文件:行号</code>），读者可以随时回到仓库中核实。</p><h2 id="关于源码版本" tabindex="-1">关于源码版本 <a class="header-anchor" href="#关于源码版本" aria-label="Permalink to &quot;关于源码版本&quot;">​</a></h2><p>本书写作时对应 <a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">deepseek-ai/deepseek-harness</a> 仓库 <code>0.1.0-rc.x</code> 版本。该项目处于 <strong>developer preview</strong> 阶段，官方明确声明&quot;THERE WILL BE COMPATIBILITY-BREAKING CHANGES&quot;（存在破坏性变更），因此书中细节可能随版本演进而变化。阅读时请以最新源码为准，本书提供的是理解源码的&quot;地图&quot;与&quot;方法论&quot;，而非一份永不失效的 API 手册。</p><h2 id="如何阅读本书" tabindex="-1">如何阅读本书 <a class="header-anchor" href="#如何阅读本书" aria-label="Permalink to &quot;如何阅读本书&quot;">​</a></h2><ul><li><strong>第一部分</strong>给出全景视角，适合所有读者；</li><li><strong>第二部分</strong>深入 Cordis 框架，是理解后续所有章节的基石，建议精读；</li><li><strong>第三、四部分</strong>按子系统展开，可挑感兴趣的章节跳读；</li><li><strong>第五部分</strong>是插件开发技巧，动手写插件前建议通读。</li></ul><p>书中大量引用了官方文档（<code>docs/</code> 目录下的 architecture、subsystems、cookbook 等），它们是官方维护的一手资料，与本书互为补充。</p><blockquote><p><strong>版本提示</strong>：本书引用的文件路径与行号基于写作时的仓库快照（commit <code>47f9438</code>，<code>0.1.0-rc.5</code>/<code>rc.6</code>）。</p></blockquote><h2 id="关于本书仓库" tabindex="-1">关于本书仓库 <a class="header-anchor" href="#关于本书仓库" aria-label="Permalink to &quot;关于本书仓库&quot;">​</a></h2><p>本书的 Markdown 源文件托管在 GitHub 仓库 <a href="https://github.com/anghunk/deepSeek-harness-docs" target="_blank" rel="noreferrer">anghunk/deepSeek-harness-docs</a>。发现错误、有改进建议或希望参与修订，欢迎在该仓库提交 issue 或 PR；每一页底部也提供&quot;在 GitHub 上编辑此页&quot;链接，可直接跳转到对应源文件。</p>',16)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
